1	/**
2	 * Orchestrator main entry point.
3	 *
4	 * Lifecycle:
5	 *   bootstrap (once) → polling loop:
6	 *     pull workspaces → eligibility → claim → briefing → adapter.run →
7	 *     side-effects → sleep → repeat
8	 *
9	 * idle_sleep_seconds controls loop behaviour (read from agent.yaml):
10	 *   0   → single-shot mode: one cycle then exit
11	 *   >0  → continuous: loops indefinitely, sleeping idle_sleep_seconds between cycles
12	 *
13	 * Exit codes:
14	 *   0  normal exit
15	 *   2  agent.yaml invalid
16	 *   3  git clone/pull failed (bootstrap only)
17	 *   4  unexpected fatal error
18	 */
19	
20	import { existsSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
21	import { join } from "node:path";
22	import { tmpdir } from "node:os";
23	import { execSync } from "node:child_process";
24	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
25	import { runBootstrap } from "./bootstrap/bootstrap.js";
26	import { resolveSSHKey } from "./resolve-ssh-key.js";
27	import { workspaceYamlPath, taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "./paths.js";
28	import { findEligibleTasks } from "./eligibility/match.js";
29	import { claimTask } from "./claim/claim-task.js";
30	import { openWorkspacePr, parseGitHubCoords } from "./claim/open-workspace-pr.js";
31	import type { Task, TaskLogEntry } from "./types/task.js";
32	import { generateBriefing } from "./briefing/agent-context.js";
33	import { fetchRagContext } from "./bootstrap/fetch-rag-context.js";
34	import { resolveModel } from "./config/resolve-model-policy.js";
35	import { parseModelOverrides } from "./config/parse-model-overrides.js";
36	import type { ModelPolicy } from "./config/resolve-model-policy.js";
37	import { pullWorkspaces } from "./poll/pull-workspaces.js";
38	import { runAgentLoop, type CycleOutcome } from "./poll/agent-loop.js";
39	import { checkInReviewPrs } from "./poll/check-in-review-prs.js";
40	import { handleMergeConflicts } from "./pr-response/auto-rebase.js";
41	import { handleDraftReviews } from "./pr-response/dispatch-draft-review.js";
42	import { handleMergedPrs, handleWorkspacePrRecoveries } from "./poll/handle-merged-prs.js";
43	import { SubProcessAdapter } from "./adapter/spawn.js";
44	import type { ExecutorInput } from "./adapter/adapter.js";
45	import { dispatchExecutorResult } from "./side-effects/dispatch.js";
46	import { buildGitEnv } from "./git-env.js";
47	
48	// ── Helpers ───────────────────────────────────────────────────────────────────
49	
50	function requireEnv(name: string): string {
51	  const val = process.env[name];
52	  if (!val) throw new Error(`Required environment variable ${name} is not set`);
53	  return val;
54	}
55	
56	function extractRepoName(url: string): string {
57	  const match = /\/([^/]+?)(?:\.git)?$/.exec(url);
58	  return match?.[1] ?? url;
59	}
60	
61	function emit(event: Record<string, unknown>): void {
62	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
63	}
64	
65	function resolveRepoLocalPath(workspaceRoot: string, repoId: string): string {
66	  type RepoEntry = { id: string; github: string; local_path?: string };
67	  const yaml = parseYaml(
68	    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
69	  ) as { repos: RepoEntry[] };
70	  const repo = yaml.repos.find((r) => r.id === repoId);
71	  if (!repo) throw new Error(`Repo "${repoId}" not found in workspace.yaml`);
72	  if (!repo.local_path?.startsWith("env:")) {
73	    throw new Error(`Repo "${repoId}" has no "local_path: env:<VAR>" declaration.`);
74	  }
75	  const envVar = repo.local_path.slice(4);
76	  const val = process.env[envVar];
77	  if (!val) throw new Error(`Env var ${envVar} is not set for repo "${repoId}".`);
78	  return val;
79	}
80	
81	function resolveRepoBaseBranch(workspaceRoot: string, repoId: string): string {
82	  type RepoEntry = { id: string; base_branch?: string };
83	  const yaml = parseYaml(
84	    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
85	  ) as { repos: RepoEntry[] };
86	  const repo = yaml.repos.find((r) => r.id === repoId);
87	  if (!repo) throw new Error(`Repo "${repoId}" not found in workspace.yaml`);
88	  return repo.base_branch ?? "main";
89	}
90	
91	function resolveRepoGitUrl(workspaceRoot: string, repoId: string): string {
92	  type RepoEntry = { id: string; github: string };
93	  const yaml = parseYaml(
94	    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
95	  ) as { repos: RepoEntry[] };
96	  const repo = yaml.repos.find((r) => r.id === repoId);
97	  if (!repo) throw new Error(`Repo "${repoId}" not found in workspace.yaml`);
98	  return repo.github;
99	}
100	
101	function resolveTaskRepoId(workspaceRoot: string, featureId: string, taskId: string): string {
102	  const task = parseYaml(
103	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
104	  ) as { repo: string };
105	  if (!task.repo) throw new Error(`Task ${taskId} has no repo field`);
106	  return task.repo;
107	}
108	
109	function loadWorkspaceModelPolicy(workspaceRoot: string): ModelPolicy {
110	  const yaml = parseYaml(
111	    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
112	  ) as { model_policy?: ModelPolicy };
113	  if (yaml.model_policy) return yaml.model_policy;
114	  const defaultPhase = { allowed: ["claude-sonnet-4-6"], default: "claude-sonnet-4-6" };
115	  return {
116	    implementation: defaultPhase,
117	    self_review: defaultPhase,
118	    pr_description: defaultPhase,
119	    suggested_next_step: { allowed: ["claude-haiku-4-5-20251001"], default: "claude-haiku-4-5-20251001" },
120	  };
121	}
122	
123	function parseManagementRepoCoords(
124	  workspaceRoot: string,
125	): { owner: string; repo: string; baseBranch: string } {
126	  type RepoEntry = { id: string; github: string; base_branch?: string };
127	  const yaml = parseYaml(
128	    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
129	  ) as { management_repo: string; repos: RepoEntry[] };
130	  const mgmtId = yaml.management_repo;
131	  const mgmtRepo = yaml.repos.find((r) => r.id === mgmtId);
132	  if (!mgmtRepo) throw new Error(`Management repo "${mgmtId}" not found in workspace.yaml`);
133	  const { owner, repo } = parseGitHubCoords(mgmtRepo.github);
134	  return { owner, repo, baseBranch: mgmtRepo.base_branch ?? "main" };
135	}
136	
137	/**
138	 * Write a rag_pre_flight log entry to the task YAML before spawning the executor.
139	 * Commits and pushes to the task branch. Throws on error.
140	 */
141	function writeRagPreFlight(
142	  workspaceRoot: string,
143	  featureId: string,
144	  taskId: string,
145	  taskBranch: string,
146	  gitAuthorEmail: string,
147	  sshKeyPath: string | undefined,
148	  ragPreFlight: { query: string; injected: boolean; summary: string },
149	): void {
150	  const now = new Date().toISOString();
151	  const entry: TaskLogEntry = {
152	    action: "rag_pre_flight",
153	    by: gitAuthorEmail,
154	    at: now,
155	    rag_context_injected: ragPreFlight.injected,
156	    rag_summary: ragPreFlight.summary,
157	    rag_query: ragPreFlight.query,
158	    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
159	  };
160	
161	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
162	  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
163	  task.log.push(entry);
164	  writeFileSync(yamlPath, yamlStringify(task), "utf-8");
165	
166	  const relPath = taskYamlRelPath(featureId, taskId);
167	  const gitOpts = {
168	    cwd: workspaceRoot,
169	    encoding: "utf-8" as const,
170	    env: buildGitEnv(sshKeyPath),
171	    timeout: 30_000,
172	    stdio: "pipe" as const,
173	  };
174	  execSync(`git add "${relPath}"`, gitOpts);
175	  execSync(
176	    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
177	    gitOpts,
178	  );
179	  execSync(`git push origin "${taskBranch}"`, gitOpts);
180	}
181	
182	// ── Main ──────────────────────────────────────────────────────────────────────
183	
184	async function main(): Promise<number> {
185	  let agentYamlPath: string;
186	  let workflowLocalPath: string;
187	  let workspacesRoot: string;
188	  let gitAuthorEmail: string;
189	
190	  try {
191	    agentYamlPath = requireEnv("AGENT_YAML_PATH");
192	    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
193	    workspacesRoot = requireEnv("WORKSPACES_ROOT");
194	    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
195	  } catch (e) {
196	    emit({ type: "fatal_missing_env", details: (e as Error).message });
197	    return 4;
198	  }
199	
200	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
201	
202	  const sshResolution = resolveSSHKey(process.env);
203	  const sshKeyPath = sshResolution.sshKeyPath;
204	  if (sshResolution.warned) {
205	    emit({ type: "warn_no_ssh_key", note: "Neither SSH_PRIVATE_KEY nor SSH_KEY_PATH is set." });
206	  }
207	
208	  const bootstrapResult = await runBootstrap({
209	    agentYamlPath,
210	    workflowLocalPath,
211	    workflowUrl: process.env.WORKFLOW_URL,
212	    workspacesRoot,
213	    sshKeyPath,
214	  });
215	
216	  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;
217	
218	  const config = bootstrapResult.config!;
219	  const githubToken = process.env.GITHUB_TOKEN ?? "";
220	  if (!githubToken) emit({ type: "warn_no_github_token" });
221	
222	  let lastPrPollAt: number | null = null;
223	
224	  async function runOneCycle(): Promise<CycleOutcome> {
225	    const pullResults = pullWorkspaces({
226	      watchUrls: config.watches,
227	      sshKeyPath,
228	      workspacesRoot,
229	      workflowUrl: process.env.WORKFLOW_URL,
230	      workflowLocalPath,
231	      emit,
232	    });
233	
234	    const haltedUrls = new Set(
235	      pullResults
236	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
237	        .map((r) => r.url),
238	    );
239	
240	    let outcome: CycleOutcome = "idle";
241	    const pulledWorkspaceRoots: string[] = [];
242	
243	    outerLoop:
244	    for (const watchUrl of config.watches) {
245	      if (haltedUrls.has(watchUrl)) continue;
246	
247	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
248	      pulledWorkspaceRoots.push(workspaceLocalPath);
249	
250	      if (!existsSync(workspaceLocalPath)) {
251	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
252	        continue;
253	      }
254	
255	      let eligibleTasks;
256	      try {
257	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
258	      } catch (e) {
259	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
260	        continue;
261	      }
262	
263	      if (eligibleTasks.length === 0) {
264	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
265	        continue;
266	      }
267	
268	      for (const { task, featureId } of eligibleTasks) {
269	        const claimResult = await claimTask({
270	          workspaceRoot: workspaceLocalPath,
271	          taskId: task.id,
272	          featureId,
273	          gitAuthorEmail,
274	          gitAuthorName,
275	          sshKeyPath,
276	          jitterMaxSeconds: config.jitter_max_seconds,
277	        });
278	
279	        const taskBranch = taskBranchName(featureId, task.id);
280	
281	        if (!claimResult.won) {
282	          if (claimResult.reason !== "branch_blocked_recovery") {
283	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
284	            continue;
285	          }
286	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
287	        } else {
288	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
289	        }
290	
291	        // ── Open management-repo PR ───────────────────────────────────────────
292	        if (githubToken) {
293	          try {
294	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
295	            await openWorkspacePr({
296	              workspaceRoot: workspaceLocalPath,
297	              featureId,
298	              taskId: task.id,
299	              branch: taskBranch,
300	              baseBranch: mgmtCoords.baseBranch,
301	              githubToken,
302	              repoOwner: mgmtCoords.owner,
303	              repoName: mgmtCoords.repo,
304	              gitAuthorEmail,
305	              gitAuthorName,
306	              sshKeyPath,
307	            });
308	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
309	          } catch (e) {
310	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e) });
311	          }
312	        }
313	
314	        // ── Resolve model + task repo ────────────────────────────────────────
315	        const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
316	        const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
317	        const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
318	        const taskBaseBranch = resolveRepoBaseBranch(workspaceLocalPath, task.repo);
319	
320	        const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
321	        let taskModelOverrides = {};
322	        try {
323	          taskModelOverrides = parseModelOverrides(readFileSync(tasksMdPath, "utf-8"), task.id);
324	        } catch { /* non-fatal */ }
325	
326	        const implementationModel = resolveModel(
327	          workspaceModelPolicy,
328	          taskModelOverrides,
329	          "implementation",
330	          task.id,
331	        );
332	
333	        // ── RAG pre-flight ───────────────────────────────────────────────────
334	        const mcpRagUrl = process.env.MCP_RAG_URL;
335	        const workspaceYaml = parseYaml(
336	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
337	        ) as { workspace_id: string };
338	        const ragQuery = `${task.title} ${featureId}`;
339	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
340	
341	        try {
342	          writeRagPreFlight(
343	            workspaceLocalPath,
344	            featureId,
345	            task.id,
346	            taskBranch,
347	            gitAuthorEmail,
348	            sshKeyPath,
349	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
350	          );
351	        } catch (e) {
352	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details: String(e) });
353	          continue;
354	        }
355	
356	        // ── Generate briefing ────────────────────────────────────────────────
357	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
358	        const baseContext = generateBriefing({
359	          taskId: task.id,
360	          featureId,
361	          taskTitle: task.title,
362	          taskBranch,
363	          taskRepo: task.repo,
364	          taskRepoRoot,
365	          workspaceRoot: workspaceLocalPath,
366	          gitAuthorEmail,
367	          gitAuthorName,
368	          implementationModel,
369	          resultPath,
370	        });
371	        const briefingContent = ragPreFlight.block
372	          ? `${baseContext}\n\n${ragPreFlight.block}`
373	          : baseContext;
374	
375	        const briefingDir = join(tmpdir(), `briefing-${task.id}`);
376	        mkdirSync(briefingDir, { recursive: true });
377	        const briefingPath = join(briefingDir, "briefing.md");
378	        writeFileSync(briefingPath, briefingContent, "utf-8");
379	
380	        // ── Build ExecutorInput ──────────────────────────────────────────────
381	        const input: ExecutorInput = {
382	          taskId: task.id,
383	          featureId,
384	          workspaceId: workspaceYaml.workspace_id,
385	          taskRepoUrl,
386	          taskRepoBranch: taskBranch,
387	          taskRepoPath: taskRepoRoot,
388	          briefingPath,
389	          resultPath,
390	          budgetTokens: config.budget.max_tokens_per_task,
391	          sshKeyPath: sshKeyPath ?? "",
392	          githubToken,
393	        };
394	
395	        // ── Run executor ─────────────────────────────────────────────────────
396	        const perTaskAdapter = new SubProcessAdapter({
397	          extraEnv: {
398	            WORKSPACE_ROOT: workspaceLocalPath,
399	            TASK_BRANCH: taskBranch,
400	            GIT_AUTHOR_EMAIL: gitAuthorEmail,
401	            GIT_AUTHOR_NAME: gitAuthorName,
402	            WORKFLOW_LOCAL_PATH: workflowLocalPath,
403	            MAX_TURNS: String(config.budget.max_iterations),
404	            LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
405	            ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
406	            ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
407	              ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
408	              : {}),
409	          },
410	        });
411	
412	        const execResult = await perTaskAdapter.run(input);
413	
414	        emit({
415	          type: "executor_result",
416	          task_id: task.id,
417	          feature_id: featureId,
418	          terminal_status: execResult.terminal_status,
419	        });
420	
421	        // ── Side-effects ─────────────────────────────────────────────────────
422	        await dispatchExecutorResult({
423	          result: execResult,
424	          workspaceRoot: workspaceLocalPath,
425	          featureId,
426	          taskId: task.id,
427	          taskBranch,
428	          taskTitle: task.title,
429	          taskRepoUrl,
430	          taskBaseBranch,
431	          githubToken,
432	          gitAuthorEmail,
433	          gitAuthorName,
434	          sshKeyPath,
435	          emit,
436	        });
437	
438	        emit({ type: "task_run_complete", task_id: task.id, feature_id: featureId, outcome: execResult.terminal_status });
439	        outcome = "ran_task";
440	        break outerLoop;
441	      }
442	    }
443	
444	    // ── In-review PR poll ─────────────────────────────────────────────────────
445	    if (githubToken) {
446	      const prPollIntervalMs =
447	        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
448	      const now = Date.now();
449	
450	      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
451	        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
452	        try {
453	          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
454	            workspaceRoots: pulledWorkspaceRoots,
455	            githubToken,
456	            emit,
457	          });
458	
459	          for (const wsRoot of pulledWorkspaceRoots) {
460	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
461	            if (wsResults.some((r) => r.mergeable === false)) {
462	              await handleMergeConflicts({
463	                prResults: wsResults,
464	                workspaceRoot: wsRoot,
465	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
466	                resolveImplBaseBranch: (repoId) => resolveRepoBaseBranch(wsRoot, repoId),
467	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
468	                gitAuthorEmail,
469	                gitAuthorName,
470	                sshKeyPath,
471	                emit,
472	              });
473	            }
474	          }
475	
476	          for (const wsRoot of pulledWorkspaceRoots) {
477	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
478	            if (wsResults.some((r) => r.hasOpenComments === true)) {
479	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
480	              await handleDraftReviews({
481	                prResults: wsResults,
482	                workspaceRoot: wsRoot,
483	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
484	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
485	                resolveImplementationModel: (fId, tId) => {
486	                  try {
487	                    const tMdPath = join(wsRoot, "docs", "features", fId, "tasks.md");
488	                    const overrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), tId);
489	                    return resolveModel(wsModelPolicy, overrides, "implementation", tId);
490	                  } catch {
491	                    return resolveModel(wsModelPolicy, {}, "implementation", tId);
492	                  }
493	                },
494	                gitAuthorEmail,
495	                gitAuthorName,
496	                sshKeyPath,
497	                workflowLocalPath,
498	                maxTurns: config.budget.max_iterations,
499	                maxTokens: config.budget.max_tokens_per_task,
500	                logSinkEnabled: config.log_sink.enabled,
501	                workspaceId: (() => {
502	                  try {
503	                    return (parseYaml(readFileSync(workspaceYamlPath(wsRoot), "utf-8")) as { workspace_id: string }).workspace_id ?? "";
504	                  } catch { return ""; }
505	                })(),
506	                githubToken,
507	                resolveImplRepoUrl: (repoId) => resolveRepoGitUrl(wsRoot, repoId),
508	                emit,
509	              });
510	            }
511	          }
512	
513	          for (const wsRoot of pulledWorkspaceRoots) {
514	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
515	            if (wsResults.some((r) => r.merged === true)) {
516	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
517	              await handleMergedPrs({
518	                prResults: wsResults,
519	                workspaceRoot: wsRoot,
520	                mgmtRepoOwner: mgmtCoords.owner,
521	                mgmtRepoName: mgmtCoords.repo,
522	                mgmtBaseBranch: mgmtCoords.baseBranch,
523	                githubToken,
524	                gitAuthorEmail,
525	                gitAuthorName,
526	                sshKeyPath,
527	                emit,
528	              });
529	            }
530	          }
531	
532	          for (const wsRoot of pulledWorkspaceRoots) {
533	            const wsRecoveries = workspacePrRecoveries.filter((r) => r.workspaceRoot === wsRoot);
534	            if (wsRecoveries.length > 0) {
535	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
536	              await handleWorkspacePrRecoveries({
537	                recoveries: wsRecoveries,
538	                mgmtRepoOwner: mgmtCoords.owner,
539	                mgmtRepoName: mgmtCoords.repo,
540	                mgmtBaseBranch: mgmtCoords.baseBranch,
541	                githubToken,
542	                gitAuthorEmail,
543	                gitAuthorName,
544	                sshKeyPath,
545	                emit,
546	              });
547	            }
548	          }
549	        } catch (e) {
550	          emit({ type: "in_review_poll_error", details: String(e) });
551	        }
552	      }
553	    }
554	
555	    return outcome;
556	  }
557	
558	  await runAgentLoop({ config, runCycle: runOneCycle, emit });
559	  return 0;
560	}
561	
562	main()
563	  .then((code) => process.exit(code))
564	  .catch((e) => {
565	    try {
566	      console.log(JSON.stringify({
567	        type: "fatal_error",
568	        details: (e as Error).message ?? String(e),
569	        at: new Date().toISOString(),
570	      }));
571	    } catch { /* last resort */ }
572	    process.exit(4);
573	  });
