1	/**
2	 * T3: GitHub API PR creation and dedup for the management (workspace) repo.
3	 *
4	 * Opens a PR from the task branch to baseBranch on the management repo at
5	 * claim time. If an open PR already exists on the branch, reuses it
6	 * (idempotent — safe to call on re-claim or after a blocked recovery).
7	 *
8	 * HTTP calls use curl via spawnSync (no gh CLI, matching pr-create convention).
9	 * Authentication: Authorization: token <githubToken>.
10	 * JSON bodies are passed as array args to spawnSync — no shell interpolation.
11	 */
12	
13	import { execSync, spawnSync } from "node:child_process";
14	import { readFileSync, writeFileSync } from "node:fs";
15	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
16	import type { Task } from "../types/task.js";
17	import { taskYamlAbsPath, taskYamlRelPath } from "../paths.js";
18	import { buildGitCommitEnv } from "../git-env.js";
19	
20	// ── Public types ──────────────────────────────────────────────────────────────
21	
22	export interface OpenWorkspacePrOpts {
23	  /** Absolute path to the management (workspace) repo root. */
24	  workspaceRoot: string;
25	  /** Feature directory ID (e.g. "task-branch-lifecycle"). */
26	  featureId: string;
27	  /** Task ID (e.g. "T3"). */
28	  taskId: string;
29	  /** Task branch name, e.g. "feature/task-branch-lifecycle-T3". */
30	  branch: string;
31	  /** PR target branch, e.g. "main". */
32	  baseBranch: string;
33	  /** GitHub personal access token. */
34	  githubToken: string;
35	  /** GitHub repo owner, parsed from workspace.yaml management repo SSH URL. */
36	  repoOwner: string;
37	  /** GitHub repo name, parsed from workspace.yaml management repo SSH URL. */
38	  repoName: string;
39	  /** GIT_AUTHOR_EMAIL for the workspace_pr commit. Defaults to "agent@unknown". */
40	  gitAuthorEmail?: string;
41	  /** GIT_AUTHOR_NAME for the workspace_pr commit. Defaults to gitAuthorEmail. */
42	  gitAuthorName?: string;
43	  /** SSH private key path for git push. Omit to rely on ambient SSH config. */
44	  sshKeyPath?: string;
45	  /**
46	   * Skip git add/commit/push for the YAML update.
47	   * The YAML is still written to disk.
48	   * Intended for unit tests that do not set up a real git repo.
49	   */
50	  skipGit?: boolean;
51	}
52	
53	export interface OpenWorkspacePrResult {
54	  prUrl: string;
55	  prNumber: number;
56	  /** True if an existing open PR was reused; false if a new PR was created. */
57	  alreadyExisted: boolean;
58	}
59	
60	// ── parseGitHubCoords ─────────────────────────────────────────────────────────
61	
62	/**
63	 * Extract GitHub owner and repo name from an SSH remote URL.
64	 *
65	 * Accepts:
66	 *   git@github.com:owner/repo.git
67	 *   git@github.com:owner/repo
68	 *
69	 * Throws a descriptive error for non-matching URLs (e.g. HTTPS or malformed).
70	 */
71	export function parseGitHubCoords(sshUrl: string): { owner: string; repo: string } {
72	  const match = /git@github\.com:([^/]+)\/([^.]+)(?:\.git)?$/.exec(sshUrl);
73	  if (!match) {
74	    throw new Error(
75	      `Cannot parse GitHub owner/repo from URL: "${sshUrl}". ` +
76	        `Expected SSH format: git@github.com:<owner>/<repo>[.git]`,
77	    );
78	  }
79	  return { owner: match[1], repo: match[2] };
80	}
81	
82	// ── Internal helpers ──────────────────────────────────────────────────────────
83	
84	interface PrListItem {
85	  html_url: string;
86	  number: number;
87	}
88	
89	/**
90	 * Call the GitHub REST API via curl. Arguments are passed as an array to
91	 * spawnSync to avoid shell injection.
92	 *
