234	/**
235	 * Iterate poll results where `merged === true` and close out each task:
236	 * mark done, activate unblocked dependents, and merge the workspace PR.
237	 */
238	export async function handleMergedPrs(opts: HandleMergedPrsOptions): Promise<void> {
239	  const {
240	    prResults,
241	    workspaceRoot,
242	    mgmtRepoOwner,
243	    mgmtRepoName,
244	    mgmtBaseBranch = "main",
245	    githubToken,
246	    gitAuthorEmail,
247	    gitAuthorName,
248	    sshKeyPath,
249	    emit,
250	  } = opts;
251	
252	  const mergedResults = prResults.filter((r) => r.merged === true);
253	  if (mergedResults.length === 0) return;
254	
255	  const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
256	  const invoker = opts.invokeClaudeForResolution ?? defaultInvokeClaudeForResolution;
257	
258	  for (const result of mergedResults) {
259	    const { taskId, featureId } = result;
260	    const taskBranch = taskBranchName(featureId, taskId);
261	    const relPath = taskYamlRelPath(featureId, taskId);
262	
263	    // ── 1. Idempotency guard: read live task state from feature branch ─────────
264	    const liveTask = tryReadTaskFromBranch(workspaceRoot, taskBranch, relPath);
265	    if (!liveTask) {
266	      emit({
267	        type: "pr_merge_skip",
268	        task_id: taskId,
269	        feature_id: featureId,
270	        reason: "task_branch_not_found",
271	      });
272	      continue;
273	    }
274	
275	    if (liveTask.status !== "in_review") {
276	      emit({
277	        type: "pr_merge_skip",
278	        task_id: taskId,
279	        feature_id: featureId,
280	        reason: `task_already_${liveTask.status}`,
281	      });
282	      continue;
283	    }
284	
285	    // ── 2. Checkout and sync feature branch ───────────────────────────────────
286	    try {
287	      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
288	      execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
289	      execSync(`git -C "${workspaceRoot}" pull --rebase origin "${taskBranch}"`, { env, stdio: "pipe" });
290	    } catch (e) {
291	      emit({
292	        type: "pr_merge_done_blocked",
293	        task_id: taskId,
294	        feature_id: featureId,
295	        reason: "branch_sync_failed",
296	        details: String(e),
297	      });
298	      continue;
299	    }
300	
301	    // ── 3. Update task YAML on disk ───────────────────────────────────────────
302	    const now = new Date().toISOString();
303	    let task: Task;
304	    try {
305	      task = parseYaml(
306	        readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
307	      ) as Task;
308	    } catch (e) {
309	      emit({
310	        type: "pr_merge_done_blocked",
311	        task_id: taskId,
312	        feature_id: featureId,
313	        reason: "task_yaml_read_failed",
314	        details: String(e),
315	      });
316	      continue;
317	    }
318	
319	    // Second idempotency check after checkout (guards against races).
320	    if (task.status !== "in_review") {
321	      emit({
322	        type: "pr_merge_skip",
323	        task_id: taskId,
324	        feature_id: featureId,
325	        reason: `task_already_${task.status}_after_checkout`,
326	      });
327	      continue;
328	    }
329	
330	    task.status = "done";
331	    task.pr = { ...task.pr, status: "merged" };
332	    task.execution.last_updated_by = gitAuthorEmail;
333	    task.execution.last_updated_at = now;
334	    task.log.push({
335	      action: "done",
336	      by: gitAuthorEmail,
337	      at: now,
338	      note: "Implementation PR merged — automated close-out by pr-merge loop.",
339	    });
340	
341	    writeFileSync(
342	      taskYamlAbsPath(workspaceRoot, featureId, taskId),
343	      yamlStringify(task),
344	      "utf-8",
345	    );
346	
347	    // ── 4. Auto-ready rule: activate sibling tasks whose deps are now satisfied
348	    const allRelPaths: string[] = [relPath];
349	    const tasksDir = join(featuresRoot(workspaceRoot), featureId, TASKS_DIR);
350	
351	    let siblingFiles: string[] = [];
352	    try {
353	      siblingFiles = readdirSync(tasksDir).filter(
354	        (f) => /^T\d+\.yaml$/.test(f) && f !== `${taskId}.yaml`,
355	      );
356	    } catch { /* best-effort — skip auto-ready if tasks dir unreadable */ }
357	
358	    // Build a status map for dependency resolution.
359	    // Start with the just-completed task (now done).
360	    const taskStatusMap = new Map<string, string>([[taskId, "done"]]);
361	    for (const sibFile of siblingFiles) {
362	      try {
363	        const sibTask = parseYaml(
364	          readFileSync(join(tasksDir, sibFile), "utf-8"),
365	        ) as Task;
366	        taskStatusMap.set(sibTask.id, sibTask.status);
367	      } catch { /* skip unreadable files */ }
368	    }
369	
370	    for (const sibFile of siblingFiles) {
371	      try {
372	        const sibPath = join(tasksDir, sibFile);
373	        const sibTask = parseYaml(readFileSync(sibPath, "utf-8")) as Task;
374	
375	        // Only consider todo tasks that depend on the just-completed task.
376	        if (sibTask.status !== "todo") continue;
377	        if (!Array.isArray(sibTask.depends_on) || !sibTask.depends_on.includes(taskId)) continue;
378	
379	        // All deps must now be done.
380	        const allDepsDone = sibTask.depends_on.every(
381	          (depId) => taskStatusMap.get(depId) === "done",
382	        );
383	        if (!allDepsDone) continue;
384	
385	        const sibNow = new Date().toISOString();
386	        sibTask.status = "ready";
387	        sibTask.log.push({
388	          action: "ready",
389	          by: gitAuthorEmail,
390	          at: sibNow,
391	          note: `Task activated — dependency ${taskId} merged and marked done.`,
392	        });
393	
394	        writeFileSync(sibPath, yamlStringify(sibTask), "utf-8");
395	        allRelPaths.push(taskYamlRelPath(featureId, sibTask.id));
396	
397	        emit({
398	          type: "task_auto_readied",
399	          task_id: sibTask.id,
400	          feature_id: featureId,
401	          activated_by: taskId,
402	        });
403	      } catch { /* skip individual sibling errors */ }
404	    }
405	
406	    // ── 5. Commit + push with rebase-and-resolve on rejection ─────────────────
407	    let pushSucceeded = false;
408	
409	    try {
410	      for (const rp of allRelPaths) {
411	        execSync(`git -C "${workspaceRoot}" add "${rp}"`, { env, stdio: "pipe" });
412	      }
413	      execSync(
414	        `git -C "${workspaceRoot}" commit -m "chore(${taskId}): mark done + activate unblocked tasks"`,
415	        { env, stdio: "pipe" },
416	      );
417	    } catch (e) {
418	      emit({
419	        type: "pr_merge_done_blocked",
420	        task_id: taskId,
421	        feature_id: featureId,
422	        reason: "commit_failed",
423	        details: String(e),
424	      });
425	      continue;
426	    }
427	
428	    const firstPush = spawnSync(
429	      "git",
430	      ["-C", workspaceRoot, "push", "origin", taskBranch],
431	      { env, encoding: "utf-8" },
432	    );
433	
434	    if (firstPush.status === 0) {
435	      pushSucceeded = true;
436	    } else {
437	      // Push rejected — attempt fetch + rebase recovery.
438	      try {
439	        execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
440	      } catch (e) {
441	        emit({
442	          type: "pr_merge_done_blocked",
443	          task_id: taskId,
444	          feature_id: featureId,
445	          reason: "fetch_failed_during_push_recovery",
446	          details: String(e),
447	        });
448	        continue;
449	      }
450	
451	      const rebaseResult = spawnSync(
452	        "git",
453	        ["-C", workspaceRoot, "rebase", `origin/${taskBranch}`],
454	        { env, encoding: "utf-8" },
455	      );
456	
457	      if (rebaseResult.status === 0) {
458	        // Clean rebase — retry push.
459	        const retryPush = spawnSync(
460	          "git",
461	          ["-C", workspaceRoot, "push", "origin", taskBranch],
462	          { env, encoding: "utf-8" },
463	        );
464	        if (retryPush.status === 0) {
465	          pushSucceeded = true;
466	        } else {
467	          emit({
468	            type: "pr_merge_done_blocked",
469	            task_id: taskId,
470	            feature_id: featureId,
471	            reason: "push_rejected_after_clean_rebase",
472	            details: retryPush.stderr ?? "",
473	          });
474	          continue;
475	        }
476	      } else {
477	        // Conflicted rebase — spawn Claude to resolve YAML conflict markers.
478	        const conflictedFiles = listConflictedFiles(workspaceRoot, env);
479	        const prompt = buildYamlConflictResolutionPrompt(workspaceRoot, conflictedFiles);
480	
481	        let resolveSucceeded = false;
482	        try {
483	          resolveSucceeded = await invoker(prompt, workspaceRoot, env);
484	        } catch { /* fall through to block */ }
485	
486	        if (resolveSucceeded) {
487	          execSync(`git -C "${workspaceRoot}" add -A`, { env, stdio: "pipe" });
488	          const continueResult = spawnSync(
489	            "git",
490	            ["-C", workspaceRoot, "rebase", "--continue"],
491	            { env: { ...env, GIT_EDITOR: "true", GIT_SEQUENCE_EDITOR: "true" }, encoding: "utf-8" },
492	          );
493	
494	          if (continueResult.status === 0) {
495	            const finalPush = spawnSync(
496	              "git",
497	              ["-C", workspaceRoot, "push", "origin", taskBranch],
498	              { env, encoding: "utf-8" },
499	            );
500	            if (finalPush.status === 0) {
501	              pushSucceeded = true;
502	            } else {
503	              spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
504	              emit({
505	                type: "pr_merge_done_blocked",
506	                task_id: taskId,
507	                feature_id: featureId,
508	                reason: "push_rejected_after_claude_rebase",
509	                details: finalPush.stderr ?? "",
510	              });
511	              continue;
512	            }
513	          } else {
514	            spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
515	            emit({
516	              type: "pr_merge_done_blocked",
517	              task_id: taskId,
518	              feature_id: featureId,
519	              reason: "rebase_continue_failed_after_claude_resolve",
520	              details: continueResult.stderr ?? "",
521	            });
522	            continue;
523	          }
524	        } else {
525	          spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
526	          emit({
527	            type: "pr_merge_done_blocked",
528	            task_id: taskId,
529	            feature_id: featureId,
530	            reason: "rebase_conflict_unresolvable",
531	            conflicted_files: conflictedFiles,
532	          });
533	          continue;
534	        }
535	      }
536	    }
537	
538	    if (!pushSucceeded) continue;
539	
540	    emit({ type: "task_marked_done", task_id: taskId, feature_id: featureId });
541	
542	    // ── 6. Merge the workspace PR via GitHub REST API ─────────────────────────
543	    if (!task.workspace_pr?.url) {
544	      emit({
545	        type: "workspace_pr_missing_for_merge",
546	        task_id: taskId,
547	        feature_id: featureId,
548	        note: "workspace_pr is null — skipping workspace PR merge. Task YAML still marked done.",
549	      });
550	      continue;
551	    }
552	
553	    // ── 6a. Rebase feature branch onto latest main before merging ─────────────
554	    try {
555	      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
556	    } catch { /* best-effort — proceed with cached origin refs */ }
557	
558	    const rebaseBeforeMerge = spawnSync(
559	      "git",
560	      ["-C", workspaceRoot, "rebase", `origin/${mgmtBaseBranch}`],
561	      { env, encoding: "utf-8" },
562	    );
563	
564	    if (rebaseBeforeMerge.status !== 0) {
565	      const conflictedFiles = listConflictedFiles(workspaceRoot, env);
566	      const prompt = buildYamlConflictResolutionPrompt(workspaceRoot, conflictedFiles);
567	      let resolveSucceeded = false;
568	      try {
569	        resolveSucceeded = await invoker(prompt, workspaceRoot, env);
570	      } catch { /* fall through */ }
571	
572	      if (resolveSucceeded) {
573	        execSync(`git -C "${workspaceRoot}" add -A`, { env, stdio: "pipe" });
574	        const continueResult = spawnSync(
575	          "git",
576	          ["-C", workspaceRoot, "rebase", "--continue"],
577	          { env: { ...env, GIT_EDITOR: "true", GIT_SEQUENCE_EDITOR: "true" }, encoding: "utf-8" },
578	        );
579	        if (continueResult.status !== 0) {
580	          spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
581	          emit({
582	            type: "workspace_pr_rebase_failed",
583	            task_id: taskId,
584	            feature_id: featureId,
585	            reason: "rebase_conflict_before_merge",
586	            conflicted_files: conflictedFiles,
587	            details: continueResult.stderr ?? "",
588	          });
589	          continue;
590	        }
591	      } else {
592	        spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
593	        emit({
594	          type: "workspace_pr_rebase_failed",
595	          task_id: taskId,
596	          feature_id: featureId,
597	          reason: "rebase_conflict_before_merge",
598	          conflicted_files: conflictedFiles,
599	          details: rebaseBeforeMerge.stderr ?? "",
600	        });
601	        continue;
602	      }
603	    }
604	
605	    const rebasePush = spawnSync(
606	      "git",
607	      ["-C", workspaceRoot, "push", "--force-with-lease", "origin", taskBranch],
608	      { env, encoding: "utf-8" },
609	    );
610	
611	    if (rebasePush.status !== 0) {
612	      emit({
613	        type: "workspace_pr_rebase_push_failed",
614	        task_id: taskId,
615	        feature_id: featureId,
616	        details: rebasePush.stderr ?? "",
617	      });
618	      continue;
619	    }
620	
621	    const coords = parsePrUrl(task.workspace_pr.url);
622	    if (!coords) {
623	      emit({
624	        type: "workspace_pr_merge_failed",
625	        task_id: taskId,
626	        feature_id: featureId,
627	        details: `Cannot parse workspace_pr.url: ${task.workspace_pr.url}`,
628	      });
629	      continue;
630	    }
631	
632	    // ── 6b. Mergeability guard — skip merge if PR has conflicts ───────────────
633	    const mergeabilityChecker = opts.checkMergeability ?? fetchPrMergeability;
634	    const mergeability = mergeabilityChecker(mgmtRepoOwner, mgmtRepoName, coords.pullNumber, githubToken);
635	    if (mergeability === false) {
636	      emit({
637	        type: "workspace_pr_not_mergeable",
638	        task_id: taskId,
639	        feature_id: featureId,
640	        workspace_pr_url: task.workspace_pr.url,
641	        note: "PR is CONFLICTING — resolve conflicts on the feature branch before retrying.",
642	      });
643	      continue;
644	    }
645	
646	    const mergeApiResult = mergeWorkspacePrViaApi(
647	      mgmtRepoOwner,
648	      mgmtRepoName,
649	      coords.pullNumber,
650	      githubToken,
651	    );
652	
653	    if (mergeApiResult.success) {
654	      emit({ type: "workspace_pr_merged", task_id: taskId, feature_id: featureId });
655	    } else {
656	      emit({
657	        type: "workspace_pr_merge_failed",
658	        task_id: taskId,
659	        feature_id: featureId,
660	        details: mergeApiResult.details,
661	      });
662	    }
663	  }
664	}
665	
666	// ── Workspace PR recovery ─────────────────────────────────────────────────────
667	
668	export interface HandleWorkspacePrRecoveriesOptions {
669	  recoveries: WorkspacePrRecovery[];
670	  mgmtRepoOwner: string;
671	  mgmtRepoName: string;
672	  /** Base branch of the management repo (default: "main"). Used for rebase-before-merge. */
673	  mgmtBaseBranch?: string;
674	  githubToken: string;
675	  gitAuthorEmail: string;
676	  gitAuthorName?: string;
677	  sshKeyPath?: string;
678	  emit: (event: Record<string, unknown>) => void;
679	  invokeClaudeForResolution?: (
680	    prompt: string,
681	    cwd: string,
682	    env: NodeJS.ProcessEnv,
683	  ) => Promise<boolean>;
684	  /**
685	   * Optional override for checking whether the workspace PR is mergeable.
686	   * Returns true (mergeable), false (conflicting — skip merge), or null (unknown — proceed).
687	   * Defaults to querying the GitHub REST API.
688	   */
689	  checkMergeability?: (
690	    owner: string,
691	    repo: string,
692	    pullNumber: number,
693	    githubToken: string,
694	  ) => boolean | null;
695	}
696	
697	/**
698	 * For each done task whose workspace PR was not merged (detected by the poll loop),
699	 * retry the merge via the GitHub REST API.
700	 *
701	 * Idempotent: if the PR is already merged, GitHub returns a non-success response
702	 * which is logged as a warning rather than an error.
703	 */
704	export async function handleWorkspacePrRecoveries(
705	  opts: HandleWorkspacePrRecoveriesOptions,
706	): Promise<void> {
707	  const { recoveries, mgmtRepoOwner, mgmtRepoName, mgmtBaseBranch = "main", githubToken, gitAuthorEmail, gitAuthorName, sshKeyPath, emit } = opts;
708	  const invoker = opts.invokeClaudeForResolution ?? defaultInvokeClaudeForResolution;
709	
710	  for (const recovery of recoveries) {
711	    const { taskId, featureId, workspaceRoot, workspacePrUrl } = recovery;
712	    const taskBranch = taskBranchName(featureId, taskId);
713	
714	    const coords = parsePrUrl(workspacePrUrl);
715	    if (!coords) {
716	      emit({
717	        type: "workspace_pr_recovery_error",
718	        task_id: taskId,
719	        feature_id: featureId,
720	        details: `Cannot parse workspace_pr URL: ${workspacePrUrl}`,
721	      });
722	      continue;
723	    }
724	
725	    emit({
726	      type: "workspace_pr_recovery_merging",
727	      task_id: taskId,
728	      feature_id: featureId,
729	      workspace_pr_url: workspacePrUrl,
730	    });
731	
732	    // Rebase onto latest main before merging.
733	    const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName ?? gitAuthorEmail, sshKeyPath);
734	
735	    try {
736	      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
737	    } catch { /* best-effort */ }
738	
739	    try {
740	      execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
741	    } catch (e) {
742	      emit({
743	        type: "workspace_pr_recovery_rebase_failed",
744	        task_id: taskId,
745	        feature_id: featureId,
746	        details: `Failed to checkout task branch: ${String(e)}`,
747	      });
748	      continue;
749	    }
750	
751	    const rebaseResult = spawnSync(
752	      "git",
753	      ["-C", workspaceRoot, "rebase", `origin/${mgmtBaseBranch}`],
754	      { env, encoding: "utf-8" },
755	    );
756	
757	    if (rebaseResult.status !== 0) {
758	      const conflictedFiles = listConflictedFiles(workspaceRoot, env);
759	      const prompt = buildYamlConflictResolutionPrompt(workspaceRoot, conflictedFiles);
760	      let resolveSucceeded = false;
761	      try {
762	        resolveSucceeded = await invoker(prompt, workspaceRoot, env);
763	      } catch { /* fall through */ }
764	
765	      if (resolveSucceeded) {
766	        execSync(`git -C "${workspaceRoot}" add -A`, { env, stdio: "pipe" });
767	        const continueResult = spawnSync(
768	          "git",
769	          ["-C", workspaceRoot, "rebase", "--continue"],
770	          { env: { ...env, GIT_EDITOR: "true", GIT_SEQUENCE_EDITOR: "true" }, encoding: "utf-8" },
771	        );
772	        if (continueResult.status !== 0) {
773	          spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
774	          emit({
775	            type: "workspace_pr_recovery_rebase_failed",
776	            task_id: taskId,
777	            feature_id: featureId,
778	            conflicted_files: conflictedFiles,
779	            details: continueResult.stderr ?? "",
780	          });
781	          continue;
782	        }
783	      } else {
784	        spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
785	        emit({
786	          type: "workspace_pr_recovery_rebase_failed",
787	          task_id: taskId,
788	          feature_id: featureId,
789	          conflicted_files: conflictedFiles,
790	          details: rebaseResult.stderr ?? "",
791	        });
792	        continue;
793	      }
794	    }
795	
796	    const pushResult = spawnSync(
797	      "git",
798	      ["-C", workspaceRoot, "push", "--force-with-lease", "origin", taskBranch],
799	      { env, encoding: "utf-8" },
800	    );
801	
802	    if (pushResult.status !== 0) {
803	      emit({
804	        type: "workspace_pr_recovery_rebase_push_failed",
805	        task_id: taskId,
806	        feature_id: featureId,
807	        details: pushResult.stderr ?? "",
808	      });
809	      continue;
810	    }
811	
812	    // Mergeability guard — skip merge if PR has conflicts.
813	    const recoveryChecker = opts.checkMergeability ?? fetchPrMergeability;
814	    const recoveryMergeability = recoveryChecker(mgmtRepoOwner, mgmtRepoName, coords.pullNumber, githubToken);
815	    if (recoveryMergeability === false) {
816	      emit({
817	        type: "workspace_pr_not_mergeable",
818	        task_id: taskId,
819	        feature_id: featureId,
820	        workspace_pr_url: workspacePrUrl,
821	        note: "PR is CONFLICTING — resolve conflicts on the feature branch before retrying.",
822	      });
823	      continue;
824	    }
825	
826	    const result = mergeWorkspacePrViaApi(
827	      mgmtRepoOwner,
828	      mgmtRepoName,
829	      coords.pullNumber,
830	      githubToken,
831	    );
832	
833	    if (result.success) {
834	      emit({ type: "workspace_pr_recovery_merged", task_id: taskId, feature_id: featureId });
835	    } else {
836	      emit({
837	        type: "workspace_pr_recovery_failed",
838	        task_id: taskId,
839	        feature_id: featureId,
840	        details: result.details,
841	      });
842	    }
843	  }
844	}
